package dev.ddaraogae.designsystem

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

// Icons of the original app (res/drawable/ic_*.xml), converted mechanically: the path
// data, viewport and colors are copied unchanged from each VectorDrawable. Single-color
// icons keep their white fill and are tinted where they are drawn, as the XML tint did.

private fun vector(name: String, width: Float, height: Float, viewportWidth: Float, viewportHeight: Float,
                   build: ImageVector.Builder.() -> Unit): ImageVector =
    ImageVector.Builder(name, width.dp, height.dp, viewportWidth, viewportHeight).apply(build).build()

private fun ImageVector.Builder.path(
    data: String, fill: Long? = null, stroke: Long? = null, strokeWidth: Float = 0f,
    cap: StrokeCap = StrokeCap.Butt, join: StrokeJoin = StrokeJoin.Miter, evenOdd: Boolean = false,
    fillAlpha: Float = 1f, strokeAlpha: Float = 1f,
) {
    addPath(PathParser().parsePathString(data).toNodes(),
        pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
        fill = fill?.let { SolidColor(Color(it)) }, fillAlpha = fillAlpha,
        stroke = stroke?.let { SolidColor(Color(it)) }, strokeAlpha = strokeAlpha,
        strokeLineWidth = strokeWidth, strokeLineCap = cap, strokeLineJoin = join)
}

